export const BODY: string = "\n<p>انسٹاگرام گرڈ اسپلٹ ایک تصویر کو نو ٹائلز میں کاٹتا ہے، جو پروفائل گرڈ میں مل کر ایک بڑی تصویر بناتی ہیں۔ یہ آپ کے پروفائل کو فنکارانہ اور نمایاں بناتا ہے۔</p>\n<p>گرڈ پزل توجہ کھینچتا ہے، مگر اسے بنانا اور برقرار رکھنا مشکل ہے۔ ایک غلط پوسٹ پوری گرڈ کو خراب کر دیتی ہے۔</p>\n<p>یہ مضمون 3 بائی 3 گرڈ، تیاری، ترتیب، پزل بمقابلہ صاف گرڈ، اور گرڈ برقرار رکھنے کی وضاحت کرتا ہے۔ کاٹنے کے لیے <a href=\"/ur/tasveer-split-karein/\">امیج اسپلٹر</a> استعمال کریں۔</p>\n<h2 id=\"what-is-an-instagram-grid-split\">انسٹاگرام گرڈ اسپلٹ کیا ہے؟</h2>\n<p>گرڈ اسپلٹ ایک تصویر کو تین بائی تین گرڈ میں کاٹتا ہے، جس سے نو ٹائلز بنتی ہیں۔ یہ نو ٹائلز پروفائل میں ایک ساتھ پوسٹ کی جاتی ہیں اور مل کر پوری تصویر بناتی ہیں۔</p>\n<p>گرڈ اسپلٹ پروفائل کو بڑی تصویر میں بدل دیتا ہے، جو دیکھنے والے کو متاثر کرتا ہے۔ یہ فنکاروں اور برانڈز میں مقبول ہے۔</p>\n<p>گرڈ اسپلٹ بنانے سے پہلے تصویر تیار کریں: وہ مربع ہونی چاہیے اور اہم حصہ درمیان میں ہونا چاہیے۔</p>\n<h2 id=\"why-split-a-photo-across-tiles\">تصویر کو ٹائلز میں کیوں بانٹیں</h2>\n<p>تصویر کو ٹائلز میں بانٹنے سے پروفائل بڑی اور نمایاں لگتی ہے۔ ایک تصویر نو پوسٹوں میں بدل جاتی ہے، جو پروفائل کو بھر دیتی ہے۔</p>\n<p>گرڈ اسپلٹ نئے فالوور کو متاثر کرتا ہے: پروفائل کھولتے ہی بڑی تصویر نظر آتی ہے۔ یہ پہلا تاثر بہت اہم ہے۔</p>\n<p>لیکن گرڈ اسپلٹ ہر تصویر کے لیے نہیں: صرف اہم تصویر، جیسے اعلان یا نئی مصنوعات، کو گرڈ میں بانٹیں۔</p>\n<h2 id=\"the-3x3-grid\">3 بائی 3 گرڈ</h2>\n<p>3 بائی 3 گرڈ سب سے عام ہے: تین قطاریں اور تین کالم، کل نو ٹائلز۔ یہ انسٹاگرام پروفائل کی تین کالم والی گرڈ سے ملتا ہے۔</p>\n<p>3 بائی 3 میں تصویر کے نو حصے بنتے ہیں، ہر ایک مربع۔ تصویر کو 3 بائی 3 میں کاٹنے سے پہلے اسے مربع کریں۔</p>\n<p>3 بائی 3 سے بڑا گرڈ، جیسے 3 بائی 4، بھی ممکن ہے، مگر وہ برقرار رکھنا مشکل ہے۔ 3 بائی 3 سے شروع کریں۔</p>\n<h2 id=\"preparing-your-source-photo\">اصل تصویر تیار کرنا</h2>\n<p>اصل تصویر مربع، تیز اور زیادہ ریزولوشن والی ہونی چاہیے۔ کم ریزولوشن والی تصویر کی ٹائلز دھندلی ہو جاتی ہیں۔</p>\n<p>تصویر تیار کرتے وقت اہم حصہ درمیان میں رکھیں، کیونکہ کونے والی ٹائلز الگ نظر آتی ہیں۔ چہرہ یا لوگو درمیان میں ہونا چاہیے۔</p>\n<p>تصویر کو تیار کرنے کے بعد اسے کراپ کریں اور پھر اسپلٹ کریں۔ تیاری کے بغیر گرڈ خراب ہو جاتا ہے۔</p>\n<h2 id=\"square-vs-non-square-sources\">مربع بمقابلہ غیر مربع اصل تصویر</h2>\n<p>مربع تصویر 3 بائی 3 میں بہترین بٹتی ہے، کیونکہ ہر ٹائل مربع بنتی ہے۔ غیر مربع تصویر کو پہلے مربع کرنا پڑتا ہے، جس سے حصہ کٹ جاتا ہے۔</p>\n<p>چوڑی تصویر کو مربع کرنے سے اس کے اطراف کٹ جاتے ہیں۔ عمودی تصویر کو مربع کرنے سے اوپر نیچے کٹ جاتا ہے۔</p>\n<p>مربع تصویر لینا بہتر ہے، یا تصویر کو اس طرح بنائیں کہ مربع کراپ میں اہم حصہ بچ جائے۔</p>\n<h2 id=\"ordering-and-uploading-tiles\">ٹائلز کی ترتیب اور اپ لوڈ</h2>\n<p>ٹائلز کو الٹی ترتیب میں اپ لوڈ کرنا ہوتا ہے: نیچے دائیں والی پہلے، اوپر بائیں والی آخر میں۔ اس سے گرڈ درست بنتا ہے۔</p>\n<p>ترتیب غلط ہونے سے تصویر بکھر جاتی ہے۔ اپ لوڈ سے پہلے ترتیب لکھ لیں اور ہر ٹائل کو نمبر سے جانچیں۔</p>\n<p>ٹائلز کو ایک ساتھ اپ لوڈ کریں، درمیان میں کوئی اور پوسٹ نہ ڈالیں۔ ایک غلط پوسٹ پوری گرڈ کو خراب کر دیتی ہے۔</p>\n<h2 id=\"puzzles-vs-clean-grids\">پزل بمقابلہ صاف گرڈ</h2>\n<p>پزل گرڈ میں ہر ٹائل تصویر کا حصہ ہوتی ہے، اور اکیلی ٹائل کا کوئی مطلب نہیں ہوتا۔ صاف گرڈ میں ہر ٹائل اکیلی بھی اچھی لگتی ہے۔</p>\n<p>پزل زیادہ متاثر کن ہے، مگر فیڈ میں ہر ٹائل الگ نظر آتی ہے اور عجیب لگتی ہے۔ صاف گرڈ کم متاثر کن ہے، مگر فیڈ میں بہتر لگتا ہے۔</p>\n<p>پزل صرف خاص موقع کے لیے چنیں، جیسے اعلان۔ روزمرہ کے لیے صاف گرڈ بہتر ہے۔</p>\n<h2 id=\"carousel-strips\">کیروسل پٹیاں</h2>\n<p>کیروسل پٹیاں تصویر کو افقی پٹیوں میں کاٹتی ہیں، جو ایک پوسٹ میں سوائپ کی جاتی ہیں۔ یہ گرڈ سے آسان ہے، کیونکہ پروفائل خراب نہیں ہوتا۔</p>\n<p>کیروسل میں صارف سوائپ کر کے پوری تصویر دیکھتا ہے۔ یہ پینوراما اور لمبی تصویر کے لیے بہترین ہے۔</p>\n<p>کیروسل پٹیاں گرڈ سے کم خطرناک ہیں: ایک غلط پوسٹ پوری پروفائل کو خراب نہیں کرتی۔</p>\n<h2 id=\"captions-and-posting-order\">کیپشن اور پوسٹ کی ترتیب</h2>\n<p>ہر ٹائل پر کیپشن لکھیں، تاکہ اکیلی ٹائل بھی سمجھ آئے۔ کیپشن میں بتائیں کہ یہ بڑی تصویر کا حصہ ہے۔</p>\n<p>پوسٹ کی ترتیب لکھ لیں اور اس پر عمل کریں۔ ترتیب بھول جانے سے گرڈ بکھر جاتا ہے۔</p>\n<p>کیپشن میں ہیش ٹیگ بھی شامل کریں، تاکہ ہر ٹائل تلاش میں آئے۔ ہر ٹائل کو الگ پوسٹ سمجھیں۔</p>\n<h2 id=\"grid-planning-apps-vs-manual\">گرڈ منصوبہ بندی ایپس بمقابلہ دستی پوسٹنگ</h2>\n<p>گرڈ منصوبہ بندی ایپس آپ کو گرڈ کا پیش منظر دکھاتی ہیں، تاکہ آپ دیکھ سکیں کہ پروفائل کیسا لگے گا۔ دستی پوسٹنگ میں اندازہ لگانا پڑتا ہے۔</p>\n<p>ایپس وقت بچاتی ہیں، مگر کچھ ایپس انسٹاگرام کے اصول توڑتی ہیں۔ دستی پوسٹنگ محفوظ ہے، مگر وقت لیتی ہے۔</p>\n<p>پہلی گرڈ کے لیے ایپ کا پیش منظر دیکھیں، مگر پوسٹ دستی کریں۔ اس سے گرڈ درست بنتا ہے اور اکاؤنٹ بھی محفوظ رہتا ہے۔</p>\n<h2 id=\"when-grids-hurt-your-feed\">گرڈ آپ کی فیڈ کو کب نقصان پہنچاتا ہے</h2>\n<p>گرڈ اس وقت نقصان پہنچاتا ہے جب ہر ٹائل الگ فیڈ میں نظر آتی ہے۔ فالوور کو ٹائل کا مطلب سمجھ نہیں آتا اور وہ اسے نظر انداز کر دیتا ہے۔</p>\n<p>گرڈ بار بار بنانے سے فیڈ بے ترتیب ہو جاتی ہے۔ ہر ہفتے گرڈ بنانا فالوور کو تھکا دیتا ہے۔</p>\n<p>گرڈ صرف خاص موقع کے لیے بنائیں۔ روزمرہ کی پوسٹوں کے لیے صاف گرڈ بہتر ہے۔</p>\n<h2 id=\"maintaining-the-grid-over-time\">وقت کے ساتھ گرڈ برقرار رکھنا</h2>\n<p>گرڈ برقرار رکھنے کے لیے ہر نئی پوسٹ کو تین کے گروپ میں ڈالیں۔ ایک پوسٹ گرڈ کو خراب کر دیتی ہے، تین پوسٹیں اسے برقرار رکھتی ہیں۔</p>\n<p>گرڈ برقرار رکھنا مشکل ہے، اس لیے بہت سے لوگ ایک گرڈ کے بعد اسے چھوڑ دیتے ہیں۔ اگر آپ برقرار نہیں رکھ سکتے تو گرڈ نہ بنائیں۔</p>\n<p>گرڈ کی منصوبہ بندی پہلے سے کریں: اگلے مہینے کی پوسٹیں لکھ لیں اور ان کی ترتیب طے کریں۔</p>\n<h2 id=\"quick-reference\">فوری حوالہ: انسٹاگرام گرڈ جانچ فہرست</h2>\n<p>گرڈ بنانے سے پہلے تصویر مربع کریں، اہم حصہ درمیان میں رکھیں، اور ٹائلز کی ترتیب لکھ لیں۔ اپ لوڈ الٹی ترتیب میں کریں اور درمیان میں کوئی پوسٹ نہ ڈالیں۔</p>\n<p>گرڈ کے بعد تین کے گروپ میں پوسٹ کریں، تاکہ گرڈ برقرار رہے۔ اسپلٹ کرنے کی مکمل رہنمائی <a href=\"/ur/blog/tasveer-splitter-rehnumai/\">امیج اسپلٹر رہنما</a> میں اور عملی مراحل <a href=\"/ur/blog/tasveer-kaise-split-karein/\">تصویر کیسے کاٹیں</a> میں دیکھیں۔</p>\n";

